package com.digiaudit.grcpc.modules.masterdata.coverage.riskcontrolobjective.api;

import com.digiaudit.grcpc.modules.masterdata.coverage.riskcontrolobjective.api.dto.CentralRiskControlObjectiveCoverageOptionsResponse; import com.digiaudit.grcpc.modules.masterdata.coverage.riskcontrolobjective.api.dto.CentralSubprocessRiskControlObjectiveCoverageResponse; import com.digiaudit.grcpc.modules.masterdata.coverage.riskcontrolobjective.application.CentralSubprocessRiskControlObjectiveCoverageQueryService; import com.digiaudit.grcpc.modules.masterdata.shared.domain.MasterDataLifecycleStatus; import java.util.List; import java.util.UUID; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/master-data/central")
public class CentralRiskControlObjectiveCoverageQueryController {
  private final CentralSubprocessRiskControlObjectiveCoverageQueryService queries; public CentralRiskControlObjectiveCoverageQueryController(CentralSubprocessRiskControlObjectiveCoverageQueryService queries){this.queries=queries;}
  @GetMapping("/subprocesses/{subprocessId}/risk-control-objective-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('RISK') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRiskControlObjectiveCoverageResponse> list(@PathVariable UUID subprocessId,@RequestParam(required=false) MasterDataLifecycleStatus status,@RequestParam(required=false) String search){return queries.listForSubprocess(subprocessId,status,search);}
  @GetMapping("/subprocesses/{subprocessId}/risk-control-objective-coverages/deleted") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('RISK') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRiskControlObjectiveCoverageResponse> deleted(@PathVariable UUID subprocessId,@RequestParam(required=false) String search){return queries.deleted(subprocessId,search);}
  @GetMapping("/subprocesses/{subprocessId}/risk-control-objective-coverages/options") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('RISK') and @masterDataAuthorization.canView('CONTROL')") public CentralRiskControlObjectiveCoverageOptionsResponse options(@PathVariable UUID subprocessId){return queries.options(subprocessId);}
  @GetMapping("/subprocesses/{subprocessId}/risk-control-objective-coverages/{coverageId}") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('RISK') and @masterDataAuthorization.canView('CONTROL')") public CentralSubprocessRiskControlObjectiveCoverageResponse detail(@PathVariable UUID subprocessId,@PathVariable UUID coverageId){return queries.detail(subprocessId,coverageId);}
  @GetMapping("/control-objectives/{controlObjectiveId}/risk-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('RISK') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRiskControlObjectiveCoverageResponse> forObjective(@PathVariable UUID controlObjectiveId,@RequestParam(required=false) String search){return queries.listForControlObjective(controlObjectiveId,search);}
  @GetMapping("/risk-templates/{riskTemplateId}/control-objective-coverages") @PreAuthorize("@masterDataAuthorization.canView('PROCESS') and @masterDataAuthorization.canView('RISK') and @masterDataAuthorization.canView('CONTROL')") public List<CentralSubprocessRiskControlObjectiveCoverageResponse> forRisk(@PathVariable UUID riskTemplateId,@RequestParam(required=false) String search){return queries.listForRisk(riskTemplateId,search);}
}
